INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('page_csr_policy', 'workspace', 'ws_csr', 'CSR policy: volunteer, donation, privacy, media', 0, '2026-08-20T09:00:00+08:00', '2026-08-20T09:00:00+08:00', '{"source": "csr"}', 'shield', NULL);
INSERT INTO pages (page_id, parent_type, parent_id, title, archived, created_time, last_edited_time, properties_json, icon, cover) VALUES ('page_privacy_handbook', 'workspace', 'ws_csr', 'Beneficiary privacy handling handbook', 0, '2026-08-20T09:00:00+08:00', '2026-08-20T09:00:00+08:00', '{"source": "legal"}', 'lock', NULL);
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_csr_1', NULL, 'page_csr_policy', 'paragraph', '{"text": "CSR donations and center support must be paid only from approved CSR funds and official payees after written approval. Team-building budgets, gift cards, personal accounts, and private reimbursements cannot pay donations or restricted community costs."}', 0, 0, 1, '2026-08-20T09:00:00+08:00', '2026-08-20T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_csr_2', NULL, 'page_csr_policy', 'paragraph', '{"text": "Material donations must match the latest community-approved list. Avoid fresh food, supplements, medical devices, gift cards, used electronics, and anything requested only by unofficial contacts."}', 0, 0, 2, '2026-08-20T09:00:00+08:00', '2026-08-20T09:00:00+08:00');
INSERT INTO blocks (block_id, parent_block_id, parent_page_id, type, content_json, has_children, archived, position, created_time, last_edited_time) VALUES ('blk_priv_1', NULL, 'page_privacy_handbook', 'paragraph', '{"text": "Beneficiary names, room or apartment numbers, phone numbers, case notes, and intake sheets are restricted personal information. Use aggregate wording for public posts and broad internal notices unless a named subject has signed release."}', 0, 0, 1, '2026-08-20T09:00:00+08:00', '2026-08-20T09:00:00+08:00');
